    "solution": "public static String season(int month, int day) {\n    int days = (month - 1) * 31 + day;\n    if (days >= 78 && days <= 170) {\n        return \"Spring\";\n    } else if (days >= 171 && days <= 263) {\n        return \"Summer\";\n    } else if (days >= 264 && days <= 356) {\n        return \"Fall\";\n    }else {\n        return \"Winter\";\n    }\n}",
