    "solution": "public static boolean allDigitsOdd(int num) {\n    boolean result = true;\n    num = Math.abs(num);\n    if (num == 0) {\n        result = false;\n    }\n    \n    while (num != 0) {\n        int digit = num % 10;\n        if (digit % 2 == 0) {\n            result = false;\n        }\n        num /= 10;\n    }\n    \n    return result;\n}",
