    "solution": "public static boolean isSorted(double[] array) {\n    double pre = array[0];\n    \n    for (int i = 1; i < array.length; i++) {\n        double current = array[i];\n        if (pre >= current) {\n            return false;\n        }\n        pre = current;\n    }\n    \n    return true;\n}",
