    "solution": "public class MinMaxAccount extends BankingAccount {\n    private int min;\n    private int max;\n    \n    public MinMaxAccount(Startup s) {\n        super(s);\n        min = getBalance();\n        max = getBalance();\n    }\n    \n    public void credit(Credit c) {\n        super.credit(c);\n        update();\n    }\n    \n    public void debit(Debit d) {\n        super.debit(d);\n        update();\n    }\n    \n    public void update() {\n        int balance = getBalance();\n        if (balance < min) {\n            min = balance;\n        } else if (balance > max) {\n            max = balance;\n        }\n    }\n    \n    public int getMin() {\n        return min;\n    }\n    \n    public int getMax() {\n        return max;\n    }\n}",
