    "solution": "public static void expunge(Stack<Integer> s) {\n    Stack<Integer> storage = new Stack<Integer>();\n    \n    if (s.size() > 1) {\n        storage.push(s.pop());\n        \n        while (!s.isEmpty()) {\n            int num = s.pop();\n            if (num >= storage.peek()) {\n                storage.push(num);\n            }\n        }\n        \n        while (!storage.isEmpty()) {\n            s.push(storage.pop());\n        }\n    }\n}",
