    "solution": "public void doubleList() {\n    if (front != null) {\n        ListNode end = front;\n        int size = 1;\n        \n        while (end.next != null) {\n            size++;\n            end = end.next;\n        }\n        \n        ListNode current = front;\n        \n        while (size > 0) {\n            size--;\n            end.next = new ListNode(current.data);\n            current = current.next;\n            end = end.next;\n        }\n        \n    }\n}",
