    "solution": "public void reverse() {\n    LinkedIntList list = new LinkedIntList();\n    \n    if (front != null) {\n        ListNode current = front.next;\n        front.next = null;\n        list.front = front;\n        \n        while (current != null) {\n            ListNode temp = current;\n            current = current.next;\n            temp.next = list.front;\n            list.front = temp;\n        }\n        \n    }\n    \n    front = list.front;\n}",
