    "solution": "public void transferFrom(LinkedIntList list) {\n    if (front == null) {\n        front = list.front;\n    } else {\n        ListNode current = front;\n        \n        while (current.next != null) {\n            current = current.next;\n        }\n        \n        current.next = list.front;\n    }\n    \n    list.front = null;\n}",
